#include <stdio.h>
int n;
void pa(int a[], int n) { for(int i=0; i<n; i++) printf("%d%c", a[i], i==n-1?'\n':' '); }
void merge(int arr[], int l, int m, int r) {
    int i, j, k; int n1 = m - l + 1; int n2 = r - m;
    int L[n1], R[n2];
    for (i = 0; i < n1; i++) L[i] = arr[l + i];
    for (j = 0; j < n2; j++) R[j] = arr[m + 1 + j];
    i = 0; j = 0; k = l;
    while (i < n1 && j < n2) {
        if (L[i] <= R[j]) { arr[k] = L[i]; i++; }
        else { arr[k] = R[j]; j++; } k++;
    }
    while (i < n1) { arr[k] = L[i]; i++; k++; }
    while (j < n2) { arr[k] = R[j]; j++; k++; }
    pa(arr, n);
}
void mergeSort(int arr[], int l, int r) {
    if (l < r) {
        int m = l + (r - l) / 2;
        mergeSort(arr, l, m);
        mergeSort(arr, m + 1, r);
        merge(arr, l, m, r);
    }
}
int main() {
    if(scanf("%d",&n)!=1) return 0;
    if(n==0) { printf("\n"); return 0; }
    int a[1005]; for(int i=0; i<n; i++) scanf("%d", &a[i]);
    if(n==1) { pa(a,n); return 0; }
    mergeSort(a, 0, n - 1);
    return 0;
}

#include <stdio.h>
int n;
void pa(int a[], int n) { for(int i=0; i<n; i++) printf("%d%c", a[i], i==n-1?'\n':' '); }
void swap(int* a, int* b) { int t = *a; *a = *b; *b = t; }
int partition(int arr[], int low, int high) {
    int pivot = arr[high]; int i = (low - 1);
    for (int j = low; j <= high - 1; j++) {
        if (arr[j] < pivot) { i++; swap(&arr[i], &arr[j]); }
    }
    swap(&arr[i + 1], &arr[high]);
    pa(arr, n);
    return (i + 1);
}
void quickSort(int arr[], int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high);
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}
int main() {
    if(scanf("%d",&n)!=1) return 0;
    if(n==0) { printf("\n"); return 0; }
    int a[1005]; for(int i=0; i<n; i++) scanf("%d", &a[i]);
    if(n==1) { pa(a,n); return 0; }
    quickSort(a, 0, n - 1);
    return 0;
}
